begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
-- Synthetic metadata only: emulate Storage API deletion transaction setting.
set local storage.allow_delete_query='true';
insert into auth.users(id,email,raw_user_meta_data) values
('32000000-0000-4000-8000-000000000001','document-a@example.test','{}'),
('32000000-0000-4000-8000-000000000002','document-b@example.test','{}'),
('32000000-0000-4000-8000-000000000003','document-inactive@example.test','{}');
update public.profiles set is_active=false where id='32000000-0000-4000-8000-000000000003';
create temp table fixture_ids(kind text primary key,id uuid);
grant all on fixture_ids to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"32000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fixture_ids select 'client',id from public.save_client(auth.uid(),null,null,'Document','Family',null,null,'EMAIL',null,null);
insert into fixture_ids select 'pet',id from public.save_patient(null,(select id from fixture_ids where kind='client'),null,'Dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fixture_ids select 'other',id from public.save_patient(null,(select id from fixture_ids where kind='client'),null,'Cat','Cat',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fixture_ids select 'encounter',id from public.save_clinical_encounter(null,(select id from fixture_ids where kind='other'),null,now(),'clinic','','','','','');
select throws_ok($$select public.prepare_patient_document('33000000-0000-4000-8000-000000000001',(select id from fixture_ids where kind='pet'),(select id from fixture_ids where kind='encounter'),'lab.pdf','application/pdf',100,'lab_result','',null,'internal')$$,'23514','Encounter does not belong to patient','Reject cross-patient encounter');
select throws_ok($$select public.prepare_patient_document('33000000-0000-4000-8000-000000000001',(select id from fixture_ids where kind='pet'),null,'lab.pdf','text/html',100,'lab_result','',null,'internal')$$,'23514',null,'Reject unsupported MIME');
select throws_ok($$select public.prepare_patient_document('33000000-0000-4000-8000-000000000001',(select id from fixture_ids where kind='pet'),null,'lab.pdf','application/pdf',20971521,'lab_result','',null,'internal')$$,'23514',null,'Reject file larger than 20 MiB');
select throws_ok($$select public.prepare_patient_document('33000000-0000-4000-8000-000000000001',(select id from fixture_ids where kind='pet'),null,'../lab.pdf','application/pdf',100,'lab_result','',null,'internal')$$,'23514',null,'Reject filename path traversal');
select lives_ok($$select public.prepare_patient_document('33000000-0000-4000-8000-000000000001',(select id from fixture_ids where kind='pet'),null,'lab.pdf','application/pdf',100,'lab_result','External lab',null,'internal')$$,'Reserve upload');
select is((select file_path from public.patient_documents where id='33000000-0000-4000-8000-000000000001'),auth.uid()::text||'/'||(select id::text from fixture_ids where kind='pet')||'/33000000-0000-4000-8000-000000000001/original','Server controls exact path');
select lives_ok($$select public.prepare_patient_document('33000000-0000-4000-8000-000000000001',(select id from fixture_ids where kind='pet'),null,'lab.pdf','application/pdf',100,'lab_result','External lab',null,'internal')$$,'Exact retry is idempotent');
select is((select count(*) from public.patient_documents),1::bigint,'Retry does not duplicate document');
select throws_ok($$select public.prepare_patient_document('33000000-0000-4000-8000-000000000001',(select id from fixture_ids where kind='pet'),null,'different.pdf','application/pdf',100,'lab_result','External lab',null,'internal')$$,'23514','Upload identifier already used with different metadata','Idempotency key cannot change metadata');
select throws_ok($$select public.finalize_patient_document('33000000-0000-4000-8000-000000000001')$$,'23514','Upload the file before finalizing','Missing object cannot finalize');
select throws_ok($$insert into storage.objects(bucket_id,name,metadata) values('patient-documents','wrong/path','{"size":100,"mimetype":"application/pdf"}')$$,'42501',null,'Cannot upload arbitrary path');
select lives_ok($$insert into storage.objects(bucket_id,name,metadata) select 'patient-documents',file_path,'{"size":99,"mimetype":"application/pdf"}'::jsonb from public.patient_documents where id='33000000-0000-4000-8000-000000000001'$$,'Own pending object upload permitted');
select is((select count(*) from storage.objects where bucket_id='patient-documents'),1::bigint,'Uploader can inspect pending object');
select throws_ok($$select public.finalize_patient_document('33000000-0000-4000-8000-000000000001')$$,'23514','Uploaded file size or MIME type does not match reservation','Actual object size checked');
select throws_ok($$select public.abandon_patient_document('33000000-0000-4000-8000-000000000001')$$,'23514','Remove the pending file before abandoning','Cannot orphan blob when abandoning');
with changed as(update storage.objects set metadata='{"size":100,"mimetype":"application/pdf"}' where bucket_id='patient-documents' returning 1) select is((select count(*) from changed),0::bigint,'No update policy permits replacing object');
select set_config('request.jwt.claims','{"sub":"32000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.patient_documents),0::bigint,'Other staff cannot see pending metadata');
select is((select count(*) from storage.objects where bucket_id='patient-documents'),0::bigint,'Other staff cannot read pending blob');
select throws_ok($$select public.finalize_patient_document('33000000-0000-4000-8000-000000000001')$$,'42501',null,'Another staff cannot finalize uploader reservation');
select throws_ok($$select public.prepare_patient_document('33000000-0000-4000-8000-000000000001',(select id from fixture_ids where kind='pet'),null,'lab.pdf','application/pdf',100,'lab_result','External lab',null,'internal')$$,'42501',null,'Another staff cannot claim idempotency key');
select set_config('request.jwt.claims','{"sub":"32000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
delete from storage.objects where bucket_id='patient-documents';
select is((select count(*) from storage.objects where bucket_id='patient-documents'),0::bigint,'Uploader can remove incorrect pending object');
insert into storage.objects(bucket_id,name,metadata) select 'patient-documents',file_path,'{"size":100,"mimetype":"image/png"}'::jsonb from public.patient_documents where id='33000000-0000-4000-8000-000000000001';
select throws_ok($$select public.finalize_patient_document('33000000-0000-4000-8000-000000000001')$$,'23514',null,'Actual MIME checked');
delete from storage.objects where bucket_id='patient-documents';
insert into storage.objects(bucket_id,name,metadata) select 'patient-documents',file_path,'{"size":100,"mimetype":"application/pdf"}'::jsonb from public.patient_documents where id='33000000-0000-4000-8000-000000000001';
select lives_ok($$select public.finalize_patient_document('33000000-0000-4000-8000-000000000001')$$,'Matching object finalizes');
select lives_ok($$select public.finalize_patient_document('33000000-0000-4000-8000-000000000001')$$,'Finalize retry idempotent');
select is((select version from public.patient_documents where id='33000000-0000-4000-8000-000000000001'),2,'Finalize retry leaves version unchanged');
delete from storage.objects where bucket_id='patient-documents';
select is((select count(*) from storage.objects where bucket_id='patient-documents'),1::bigint,'Ready original cannot be deleted');
select throws_ok($$update public.patient_documents set created_by='32000000-0000-4000-8000-000000000002'$$,'42501',null,'Direct metadata and actor writes denied');
select throws_ok($$select public.void_patient_document('33000000-0000-4000-8000-000000000001',1,'Wrong record')$$,'40001',null,'Stale void rejected');
select throws_ok($$select public.void_patient_document('33000000-0000-4000-8000-000000000001',2,' ')$$,'23514',null,'Void reason required');
select set_config('request.jwt.claims','{"sub":"32000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from storage.objects where bucket_id='patient-documents'),1::bigint,'Active staff can read finalized document');
select lives_ok($$select public.void_patient_document('33000000-0000-4000-8000-000000000001',2,'Uploaded to wrong record')$$,'Staff may void retaining history');
select is((select voided_by from public.patient_documents where id='33000000-0000-4000-8000-000000000001'),auth.uid(),'Void actor is server stamped');
delete from storage.objects where bucket_id='patient-documents';
select is((select count(*) from storage.objects where bucket_id='patient-documents'),1::bigint,'Voided original retained');
update public.pets set archived_at=now() where id=(select id from fixture_ids where kind='pet');
select lives_ok($$select public.prepare_patient_document('33000000-0000-4000-8000-000000000002',(select id from fixture_ids where kind='pet'),null,'consent.pdf','application/pdf',100,'consent','',null,'internal')$$,'Archived patient accepts historical documents');
select lives_ok($$select public.abandon_patient_document('33000000-0000-4000-8000-000000000002')$$,'Empty pending reservation can be abandoned');
select lives_ok($$select public.abandon_patient_document('33000000-0000-4000-8000-000000000002')$$,'Abandon retry idempotent');
select throws_ok($$insert into storage.objects(bucket_id,name,metadata) select 'patient-documents',file_path,'{"size":100,"mimetype":"application/pdf"}'::jsonb from public.patient_documents where id='33000000-0000-4000-8000-000000000002'$$,'42501',null,'Abandoned reservation cannot receive blob');
select set_config('request.jwt.claims','{"sub":"32000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is((select count(*) from public.patient_documents),0::bigint,'Inactive staff cannot read metadata');
select is((select count(*) from storage.objects where bucket_id='patient-documents'),0::bigint,'Inactive staff cannot read blobs');
select throws_ok($$select public.finalize_patient_document('33000000-0000-4000-8000-000000000001')$$,'42501','Active staff access required','Inactive staff cannot mutate');
set local role anon;
select throws_ok($$select * from public.patient_documents$$,'42501',null,'Anonymous metadata access denied');
select throws_ok($$select public.finalize_patient_document('33000000-0000-4000-8000-000000000001')$$,'42501',null,'Anonymous RPC denied');
reset role;
select ok(exists(select 1 from public.audit_logs where table_name='patient_documents' and user_id='32000000-0000-4000-8000-000000000002'),'Document changes audited');
select is((select public from storage.buckets where id='patient-documents'),false,'Document bucket private');
select is((select file_size_limit from storage.buckets where id='patient-documents'),20971520::bigint,'Storage enforces 20 MiB size limit');
select is((select allowed_mime_types from storage.buckets where id='patient-documents'),array['application/pdf','image/jpeg','image/png'],'Storage limits MIME allowlist');
select * from finish();
rollback;
